import requests
import json
import os
import sys
import re
try:
  base_url = os.environ["LAB_URL"]
  token = os.environ["LAB_TOKEN"]
except Exception:
  sys.stderr.write("missing env\n")
  sys.exit(2)
base_url = base_url.rstrip("/")
headers = {"Authorization": "Bearer " + token}
all_users = []
next_url = base_url + "/api/users"
page_num = 1
pages_read = 0
while next_url:
  resp = requests.get(next_url, headers=headers)
  if resp.status_code != 200:
    sys.stderr.write("GET users failed\n")
    sys.exit(2)
  try:
    data = resp.json()
  except Exception:
    sys.stderr.write("bad json\n")
    sys.exit(2)
  if isinstance(data, list):
    page_items = data
  elif isinstance(data, dict):
    page_items = None
    for k in data:
      if isinstance(data[k], list):
        page_items = data[k]
        break
    if page_items is None:
      sys.stderr.write("unexpected data format\n")
      sys.exit(2)
  else:
    sys.stderr.write("unexpected data format\n")
    sys.exit(2)
  for item in page_items:
    all_users.append(item)
  pages_read = pages_read + 1
  if pages_read > 100:
    sys.stderr.write("too many pages\n")
    sys.exit(2)
  nxt = None
  links = resp.links
  if "next" in links:
    raw = links["next"]["url"]
    if raw.startswith("http://") or raw.startswith("https://"):
      nxt = raw
    else:
      if raw.startswith("/"):
        nxt = base_url + raw
      else:
        nxt = base_url + "/" + raw
  if nxt is not None:
    next_url = nxt
    page_num = page_num + 1
    continue
  tot = None
  if "X-Total-Pages" in resp.headers:
    try:
      tot = int(resp.headers["X-Total-Pages"])
    except Exception:
      sys.stderr.write("bad paging header\n")
      sys.exit(2)
  if tot is not None:
    if page_num < tot:
      page_num = page_num + 1
      next_url = base_url + "/api/users?page=" + str(page_num)
      continue
  next_url = None
ev_resp = requests.get(base_url + "/admin/users", headers=headers)
if ev_resp.status_code != 200:
  sys.stderr.write("GET evidence failed\n")
  sys.exit(2)
admins = []
for u in all_users:
  if "role" not in u or "login" not in u or "email" not in u:
    sys.stderr.write("missing fields\n")
    sys.exit(2)
  if u["role"] == "admin":
    admins.append(u)
login_re = re.compile(r"^[A-Za-z]\.[A-Za-z]+(?:-[A-Za-z]+)?$")
email_basic_re = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
name_like_re = re.compile(r"^[A-Za-z]+[.\-_][A-Za-z]+(?:[.\-_][A-Za-z]+)*$")
bad = []
for a in admins:
  login = a["login"]
  email = a["email"]
  if not isinstance(login, str) or not isinstance(email, str):
    sys.stderr.write("bad types\n")
    sys.exit(2)
  login_ok = True
  if login_re.match(login) is None:
    login_ok = False
  else:
    parts = re.split(r"[.\-_]+", login.lower())
    func = ["admin", "administrateur", "root", "sysadmin", "superuser", "support", "contact", "info", "help", "helpdesk", "service", "team", "shared", "generic", "generique", "test", "demo", "conseiller"]
    for p in parts:
      if p in func:
        login_ok = False
  email_ok = True
  if email_basic_re.match(email) is None:
    email_ok = False
  else:
    at = email.split("@")
    if len(at) != 2:
      email_ok = False
    else:
      local = at[0]
      low = local.lower()
      shared = ["admin", "administrateur", "root", "sysadmin", "superuser", "support", "contact", "info", "helpdesk", "help", "service", "team", "shared", "generic", "generique", "accueil", "standard", "direction", "agence", "exploitation", "production", "astreinte", "securite", "security", "backoffice", "conseiller", "banque", "kerlann"]
      for kw in shared:
        if kw in low:
          email_ok = False
      if "." not in local and "_" not in local and "-" not in local:
        email_ok = False
      if name_like_re.match(local) is None:
        email_ok = False
  if not login_ok or not email_ok:
    bad.append(a)
expected = "for all users where role == admin: login matches initiale.nom pattern and email is personal, with no function login and no shared mailbox"
if len(bad) == 0:
  observed = []
  for a in admins:
    observed.append({"login": a["login"], "email": a["email"], "role": a["role"]})
  detail = "Checked " + str(len(admins)) + " admin account(s) across " + str(pages_read) + " page(s): all have nominative initiale.nom logins and personal emails."
  print(json.dumps({"status": "pass", "observed": observed, "expected": expected, "detail": detail, "evidence_page": "/admin/users"}))
else:
  observed = []
  for b in bad:
    observed.append({"login": b["login"], "email": b["email"], "role": b["role"]})
  detail = "Found " + str(len(bad)) + " generic or shared admin account(s) out of " + str(len(admins)) + " admin account(s) across " + str(pages_read) + " page(s)."
  print(json.dumps({"status": "fail", "observed": observed, "expected": expected, "detail": detail, "evidence_page": "/admin/users"}))
